    f.gs.Exp.rgPrimaryExp[1]!.wExp = 50
    // battle.c:1238-1282:health权重2/3,100*2/3截断后再乘2=132;attack权重不足一次涨点。
    f.gs.Exp.rgHealthExp[1] = { wExp: 0, wLevel: 1, wCount: 2 }
